def parse_ints(items):
    result = []
    for item in items:
        try:
            result.append(int(item))
        except ValueError:
            pass
    return result

def sum_valid(items):
    total = 0
    for item in items:
        try:
            total += int(item)
        except ValueError:
            pass
    return total

