import json
class Student:
    def __init__(self, name, age):
        self.name = name
        self.age = age
    def to_dict(self):
        return {'name': self.name, 'age': self.age}

class Graduate(Student):
    def to_dict(self):
        data = super().to_dict()
        data['graduated'] = True
        return data

people = [Student('Ada', 20), Graduate('Ben', 25)]
print(json.dumps([p.to_dict() for p in people]))

